contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address newDao, bool wasConfigured) public payable {
        require(true);

        address daoBefore = c.DAO();
        bool configuredBefore = c.configured();

        // Make the deciding call. We only exercise inputs for which the call is
        // expected to succeed: msg.sender (this contract) is either the current
        // DAO, or c is not configured, or newDao is zero.
        bool allowed = (daoBefore == address(0))
            || (daoBefore == address(this))
            || (!configuredBefore)
            || (newDao == address(0))
            || (newDao == daoBefore);

        bool reverted;
        if (allowed) {
            try c.setDAO(newDao) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.setDAO(newDao) {
                reverted = true;
            } catch {
                reverted = false;
            }
        }

        address daoAfter = c.DAO();

        // General rule:
        // - If the setDAO call was permitted (either it reverted when it should
        //   not have, or it succeeded when it was allowed), then DAO equals the
        //   new argument exactly. Otherwise DAO is unchanged.
        if (allowed) {
            assert(!reverted);
            assert(daoAfter == newDao);
        } else {
            assert(reverted);
            assert(daoAfter == daoBefore);
        }
    }

    receive() external payable {}
}

