contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address newDAO) public {
        require(newDAO != address(0), "precondition: nonzero DAO address");

        bool wasConfigured = c.configured();
        address oldDAO = c.DAO();

        bool reverted;
        try c.setDAO(newDAO) {
            reverted = false;
        } catch {
            reverted = true;
        }

        bool shouldRevert = wasConfigured && msg.sender != oldDAO && msg.sender != newDAO;
        assert(reverted == shouldRevert);

        if (reverted) {
            assert(c.DAO() == oldDAO);
            assert(c.configured() == wasConfigured);
        } else {
            assert(c.DAO() == newDAO);
        }
    }
}

