contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address[] calldata governables, bool[] calldata isGoverned, uint256 idx) public {
        require(governables.length == isGoverned.length, "length mismatch");
        require(governables.length > 0, "empty array");
        require(idx + 1 < governables.length, "idx must not be the last index");

        c.setGoverned(governables, isGoverned);

        bool overwrittenLater = false;
        for (uint256 j = idx + 1; j < governables.length; j++) {
            if (governables[j] == governables[idx]) {
                overwrittenLater = true;
            }
        }

        if (!overwrittenLater) {
            assert(c.governed(governables[idx]) == isGoverned[idx]);
        } else {
            assert(true);
        }
    }

    receive() external payable {}
}

