contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        uint8 maxGovernanceChangePerEpoch,
        uint256 epochSize,
        uint8 changeTolerance
    ) public {
        uint256 beforeMax = c.security();
        uint256 beforeEpoch = c.security();
        uint256 beforeTol = c.security();

        bool reverted;
        try c.configureSecurityParameters(maxGovernanceChangePerEpoch, epochSize, changeTolerance) {
            reverted = false;
        } catch {
            reverted = true;
        }

        (uint256 afterMax, uint256 afterEpoch, uint8 afterTol) = c.security();

        if (changeTolerance >= 100) {
            assert(reverted);
        } else {
            assert(!reverted);
            assert(afterMax == maxGovernanceChangePerEpoch);
            assert(afterEpoch == epochSize);
            assert(afterTol == changeTolerance);
        }
    }
}

