contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address target, address asset, uint256 amount) public payable {
        // Setup: configure flash governance so that a decision could exist.
        c.configureFlashGovernance(asset, amount, 0, false);

        // Read the pending decision before withdrawal attempt.
        (uint256 storedAmount, uint256 unlockTime, address storedAsset, bool burnable) = c.pendingFlashDecision(target, address(this));

        // Attempt to withdraw. The caller (this contract) has no pending decision for (target, asset) in
        // the initial state, so the call must revert.
        bool reverted;
        try c.withdrawGovernanceAsset(target, asset) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: withdrawal must revert for all inputs because no pending decision has been
        // created for the caller (msg.sender) via assertGovernanceApproved. The function deletes the
        // pending decision on success, so a successful withdrawal would require amount > 0 and a
        // matching asset and an expired unlock time; none of these can be true before the call since
        // pendingFlashDecision was never populated.
        assert(reverted);
    }
}

contract InvMutTest {
