        } catch {
            reverted = true;
        }

        (uint256 storedAmount, uint256 storedUnlockTime, address storedAsset,) = c.pendingFlashDecision(target, address(this));

        assert(
            reverted == (storedAmount == 0 || storedAsset != asset || storedUnlockTime >= block.timestamp)
        );
    }

