contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address newDao) public payable {
        require(newDao != address(0), "test: zero DAO would be meaningless");

        // Read the pre-state through the public getter.
        address oldDaoBefore = c.DAO();
        bool configuredBefore = c.configured();

        // Only attempt the call when it is actually allowed by P's own rule:
        // allowed if not configured OR caller == old DAO. Since msg.sender for c
        // is this test contract, the second branch can only be the old DAO if
        // this test contract equals old DAO. We drive the call as a top-level
        // statement and capture the revert flag.
        bool reverted;
        try c.setDAO(newDao) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            // General rule: a successful setDAO stores the argument as DAO.
            assert(c.DAO() == newDao);
        } else {
            // If it reverted, DAO must be unchanged from its pre-call value.
            assert(c.DAO() == oldDaoBefore);
            // And the revert can only have happened because the caller was not
            // permitted: contract was configured and sender was not old DAO.
            assert(configuredBefore && oldDaoBefore != address(this));
        }
    }
}

