contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 v1, uint256 v2) public payable {
        // Drive the public entry point: make sure limits are active for this test contract.
        c.setEnforcement(true);

        // Snapshot the enforcement flag, and the security tolerance, through public getters.
        bool active = c.enforceLimitsActive(address(this));
        (uint256 epochSize, uint256 lastAct, uint8 maxChange, uint8 tolerance) = c.security();
        bool isConfigured = c.configured();

        bool reverted;
        try c.enforceTolerance(v1, v2) { reverted = false; } catch { reverted = true; }

        // The contract returns early (does not enforce) whenever limits are inactive
        // or when the caller is not configured (its configured() reads false), so in
        // those cases no tolerance check applies and the call must complete.
        // When both preconditions hold, the call reverts exactly when the relative
        // difference is not strictly below the configured tolerance.
        bool shouldRevert;
        if (!active || !isConfigured) {
            shouldRevert = false;
        } else if (v1 > v2) {
            if (v2 == 0) {
                shouldRevert = !(v1 <= 1);
            } else {
                shouldRevert = !((v1 - v2) * 100 < tolerance * v1);
            }
        } else {
            if (v1 == 0) {
                shouldRevert = !(v2 <= 1);
            } else {
                shouldRevert = !((v2 - v1) * 100 < tolerance * v1);
            }
        }
        assert(reverted == shouldRevert);
    }

    receive() external payable {}
}

