    function run(address dao) public payable {
        require(dao != address(0), "test input must be nonzero DAO candidate");

        address beforeDAO = c.DAO();
        bool configuredBefore = c.configured();
        address caller = address(this);

        bool reverted;
        try c.setDAO(dao) { reverted = false; } catch { reverted = true; }

        // General rule: setDAO must revert unless the caller is the current DAO,
        // or the current DAO is address(0), or the contract is not configured yet.
        bool allowed = (caller == beforeDAO) || (beforeDAO == address(0)) || (!configuredBefore);
        assert(reverted == !allowed);

        // When allowed and the call succeeded, the DAO getter must reflect the new argument.
        if (!reverted && allowed) {
            assert(c.DAO() == dao);
        }
    }
    receive() external payable {}
}

