        bool successRecorded = true;
        if (!reverted) {
            for (uint256 i = 0; i < governables.length; i++) {
                if (c.governed(governables[i]) != isGoverned[i]) {
                    successRecorded = false;
                    break;
                }
            }
        } else {
            for (uint256 i = 0; i < governables.length; i++) {
                if (c.governed(governables[i]) != beforeFlags[i]) {
                    successRecorded = false;
                    break;
                }
            }
        }

        assert(reverted == (governables.length != isGoverned.length) && successRecorded);
    }

    receive() external payable {}
}

