contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        address target,
        address asset,
        uint256 amount,
        uint256 unlockTime,
        bool assetBurnable,
        uint8 maxGovernanceChangePerEpoch,
        uint256 epochSize,
        uint8 changeTolerance,
        bool emergency
    ) public payable {
        require(target != address(0), "target");
        require(asset != address(0), "asset");

        c.configureFlashGovernance(asset, amount, unlockTime, assetBurnable);
        c.configureSecurityParameters(maxGovernanceChangePerEpoch, epochSize, changeTolerance);

        (uint256 beforeAmount, uint256 beforeUnlockTime, address beforeAsset, bool beforeBurnable) = c.flashGovernanceConfig();

        (uint256 beforeSecurityEpochSize, uint256 beforeSecurityLastAct, uint8 beforeSecurityMaxChange, uint8 beforeSecurityTolerance) = c.security();

        uint256 beforeLastAct = beforeSecurityLastAct;
        bool hasPending = false;
        uint256 pendingUnlockTime = 0;
        {
            (uint256 pAmount, uint256 pUnlockTime, address pAsset, bool pBurnable) = c.pendingFlashDecision(target, msg.sender);
            hasPending = pAsset != address(0);
            pendingUnlockTime = pUnlockTime;
        }

        bool reverted;
        try c.assertGovernanceApproved(msg.sender, target, emergency) {
            reverted = false;
        } catch {
            reverted = true;
        }

        (
            uint256 afterAmount,
            uint256 afterUnlockTime,
            address afterAsset,
            bool afterBurnable
        ) = c.pendingFlashDecision(target, msg.sender);

        (
            uint256 afterSecurityEpochSize,
            uint256 afterSecurityLastAct,
            uint8 afterSecurityMaxChange,
            uint8 afterSecurityTolerance
        ) = c.security();

        bool windowOpen = emergency || (block.timestamp - beforeLastAct > beforeSecurityEpochSize);
        bool priorExpired = pendingUnlockTime < block.timestamp;
        bool expectedSuccess = windowOpen && priorExpired;

        if (expectedSuccess) {
            assert(!reverted);
            assert(afterAsset == asset);
            assert(afterAmount == amount);
            assert(afterBurnable == assetBurnable);
            assert(afterUnlockTime >= block.timestamp);
            assert(afterSecurityLastAct == block.timestamp);
        } else {
            assert(reverted);
            assert(afterAsset == beforeAsset);
            assert(afterAmount == beforeAmount);
            assert(afterUnlockTime == beforeUnlockTime);
            assert(afterBurnable == beforeBurnable);
            assert(afterSecurityLastAct == beforeSecurityLastAct);
        }

        assert(afterSecurityEpochSize == beforeSecurityEpochSize);
        assert(afterSecurityMaxChange == beforeSecurityMaxChange);
        assert(afterSecurityTolerance == beforeSecurityTolerance);
        assert(afterAsset == asset || afterAsset == beforeAsset);
    }

    receive() external payable {}
}

