contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 p1, uint256 p2, bool setMax) public {
        c.configureSecurityParameters(0, 1, 0);

        if (setMax) {
            c.configureSecurityParameters(0, 1, 100);
        }

        int256 v1 = p1 > uint256(type(int256).max) ? type(int256).max : int256(p1);
        int256 v2 = p2 > uint256(type(int256).max) ? type(int256).max : int256(p2);

        uint256 uv1 = v1 < 0 ? uint256(-v1) : uint256(v1);
        uint256 uv2 = v2 < 0 ? uint256(-v2) : uint256(v2);

        bool revertedInt;
        bool revertedUint;

        try c.enforceToleranceInt(v1, v2) {
            revertedInt = false;
        } catch {
            revertedInt = true;
        }

        try c.enforceTolerance(uv1, uv2) {
            revertedUint = false;
        } catch {
            revertedUint = true;
        }

        if (setMax) {
            assert(revertedInt == revertedUint);
        } else {
            assert(revertedUint || !revertedInt);
        }
    }
}

